// Shopping cart utilities — small pure-JS module under test.
export class Cart {
  constructor() {
    this.items = [];
    this.discount = 0; // percent, 0-100
  }

  addItem(name, price, qty = 1) {
    if (typeof price !== "number" || price < 0) {
      throw new Error("price must be a non-negative number");
    }
    if (!Number.isInteger(qty) || qty < 1) {
      throw new Error("qty must be a positive integer");
    }
    this.items.push({ name, price, qty });
  }

  setDiscount(percent) {
    if (percent < 0 || percent > 100) {
      throw new Error("discount must be between 0 and 100");
    }
    this.discount = percent;
  }

  // BUG: subtotal is wrong — it ignores qty entirely.
  subtotal() {
    let sum = 0;
    for (const it of this.items) {
      sum += it.price;
    }
    return sum;
  }

  // BUG: total applies the discount in the wrong direction
  // (a 10% discount should remove 10%, not add it).
  total() {
    const sub = this.subtotal();
    return sub + (sub * this.discount) / 100;
  }

  // BUG: this should merge duplicate items with the same name into one
  // entry with combined qty, but it returns empty array when no duplicates
  // exist (it should return the items unchanged in that case).
  mergeDuplicates() {
    const seen = new Map();
    const out = [];
    for (const it of this.items) {
      if (seen.has(it.name)) {
        const idx = seen.get(it.name);
        out[idx] = { ...it, qty: out[idx].qty + it.qty };
      } else {
        seen.set(it.name, out.length);
        out.push(it);
      }
    }
    return out.length === this.items.length ? [] : out;
  }
}

content.thinking:
The test results confirm the three identified bugs and provide expected values:

1.  **`subtotal()`**: Expected 4.4, got 1.7. The fix is to multiply `price` by `qty`.
2.  **`total()`**: Expected 63, got 55. The fix is to subtract the discount amount, not add it.
3.  **`mergeDuplicates()`**: Expected 2 (meaning the original two unique items should be returned), got 0 (meaning it returned an empty array). The fix is to return `this.items` if no merging occurred.

I will apply these fixes to `lib/cart.js`.

**Fix 1: `subtotal()`**
Current:
```javascript
  subtotal() {
    let sum = 0;
    for (const it of this.items) {
      sum += it.price;
    }
    return sum;
  }
```
Needs to be:
```javascript
  subtotal() {
    let sum = 0;
    for (const it of this.items) {
      sum += it.price * it.qty; // Multiply by qty
    }
    return sum;
  }
```

**Fix 2: `total()`**
Current:
```javascript
  total() {
    const sub = this.subtotal();
    return sub + (sub * this.discount) / 100; // Adds discount
  }
```
Needs to be:
```javascript
  total() {
    const sub = this.subtotal();
    return sub - (sub * this.discount) / 100; // Subtracts discount
  }
```

**Fix 3: `mergeDuplicates()`**
Current:
```javascript
  mergeDuplicates() {
    const seen = new Map();
    const out = [];
    for (const it of this.items) {
      if (seen.has(it.name)) {
        const idx = seen.get(it.name);
        out[idx] = { ...it, qty: out[idx].qty + it.qty };
      } else {
        seen.set(it.name, out.length);
        out.push(it);
      }
    }
    return out.length === this.items.length ? [] : out; // Incorrect return if no duplicates
  }
```
Needs to be:
```javascript
  mergeDuplicates() {
    const seen = new Map();
    const out = [];
    for (const it of this.items) {
      if (seen.has(it.name)) {
        const idx = seen.get(it.name);
        out[idx] = { ...it, qty: out[idx].qty + it.qty };
      } else {
        seen.set(it.name, out.length);
        out.push(it);
      }
    }
    return out.length === this.items.length ? this.items : out; // Return original items if no merge
  }
```
Wait, checking the original implementation logic: `out.length === this.items.length` means *no* merges happened (because a merge reduces the final length compared to the initial items, assuming all items are unique or merged). If `out.length === this.items.length`, it means every item was pushed to `out` as a new entry, so no duplicates were found or merged. In this case, it should return `this.items`.

